import {Injectable,inject} from '@angular/core';
import {BehaviorSubject,EMPTY,Observable,of,Subject,timer} from 'rxjs';
import {catchError,exhaustMap,map,tap} from 'rxjs/operators';
import type {BookletError,CommandResponse,Profile,TestSessionData} from './group-monitor.interfaces';
import type {ConnectionStatus} from '../shared/shared.module';
import {NativeMonitorSessionService} from '../native-session.service';
import {parseNativeMonitorSnapshot,nativeMonitorSelectionBody} from '../native-monitor-wire';
@Injectable()
export class BackendService {
 private readonly session=inject(NativeMonitorSessionService);
 readonly connectionStatus$=new BehaviorSubject<ConnectionStatus>('initial');
 readonly problem$=new BehaviorSubject('');
 private readonly connectionClosed=new Subject<void>();
 readonly connectionClosed$=this.connectionClosed.asObservable();
 get cacheIdentity(){return this.session.access();}
 get accessSignal(){return this.session.accessSignal;}
 private request(method:string,path:string,body?:unknown,raw=false):Observable<string>{
  return new Observable(subscriber=>{
   const abort=new AbortController();
   void this.session.text(method,path,body,undefined,raw,abort.signal)
    .then(text=>{if(!subscriber.closed){subscriber.next(text);subscriber.complete();}})
    .catch(error=>{if(!subscriber.closed)subscriber.error(error);});
   return()=>abort.abort();
  });
 }
 observeSessionsMonitor(groupName:string):Observable<TestSessionData[]>{
  return timer(0,5000).pipe(exhaustMap(()=>{
   this.connectionStatus$.next('polling-fetch');
   return this.request('GET','/monitor/group/'+encodeURIComponent(groupName)+'/test-sessions').pipe(
    map(parseNativeMonitorSnapshot),
    tap(()=>{this.connectionStatus$.next('polling-sleep');this.problem$.next('');}),
    // An error is never an empty successful snapshot. The next tick can retry.
    catchError(error=>{this.connectionStatus$.next('error');this.problem$.next(error instanceof Error?error.message:'Verbindungsfehler');return EMPTY;})
   );
  }));
 }
 cutConnection(){this.connectionClosed.next();this.connectionStatus$.next('initial');this.problem$.next('');}
 getBooklet(name:string):Observable<string|BookletError>{return this.request('GET','/booklet/'+encodeURIComponent(name)).pipe(catchError(error=>of({error:error.status===404?'missing-file':'general',species:null} as BookletError)));}
 private write(path:string,ids:string[],fields:Record<string,unknown>={},method='POST'):Observable<CommandResponse>{
  return this.request(method,path,nativeMonitorSelectionBody(ids,fields),true).pipe(map(()=>({commandType:String(fields['keyword']??(path.endsWith('/unlock')?'unlock':'lock')),testIds:ids})),tap(()=>this.problem$.next('')),catchError(error=>{this.problem$.next(error instanceof Error?error.message:'Befehl fehlgeschlagen');throw error;}));
 }
 command(keyword:string,args:string[],testIds:string[]):Observable<CommandResponse>{return this.write('/monitor/command',testIds,{keyword,arguments:args,timestamp:Date.now()/1000},'PUT');}
 unlock(group:string,ids:string[]){return this.write('/monitor/group/'+encodeURIComponent(group)+'/tests/unlock',ids);}
 lock(group:string,ids:string[]){return this.write('/monitor/group/'+encodeURIComponent(group)+'/tests/lock',ids);}
 getProfile(id:string):Observable<Profile>{return this.request('GET','/monitor/profile/'+encodeURIComponent(id)).pipe(map(text=>JSON.parse(text) as Profile));}
}
import { Injectable } from '@angular/core';
import { defer, EMPTY, fromEvent, merge, Observable, of } from 'rxjs';
import { finalize, map, shareReplay, takeUntil, tap } from 'rxjs/operators';
import { BackendService } from '../backend.service';
import {
  isBooklet, isUnit, type Booklet, type Testlet, type BookletError, type Unit, type BookletState, type BookletStateOption
} from '../group-monitor.interfaces';
import { BookletParserService } from '../../shared/services/booklet-parser.service';
import {
  BookletConfig, type BookletMetadata, type BookletStateDef, type BookletStateOptionDef, type ContextInBooklet, type TestletDef, type UnitDef
} from '../../shared/shared.module';

@Injectable()
export class BookletService extends BookletParserService<Unit, Testlet, BookletStateOption, BookletState, Booklet> {
  private readonly booklets: { [k: string]: Observable<Booklet | BookletError> } = {};

  constructor(private bs: BackendService) {
    super();
  }

  private accessIdentity: unknown;
  getBooklet(bookletName = ''): Observable<Booklet | BookletError> {
    if (this.accessIdentity !== this.bs.cacheIdentity) {
      for (const name of Object.keys(this.booklets)) delete this.booklets[name];
      this.accessIdentity = this.bs.cacheIdentity;
    }
    if (typeof this.booklets[bookletName] !== 'undefined') {
      return this.booklets[bookletName];
    }
    if (bookletName === '') {
      this.booklets[bookletName] = of<Booklet | BookletError>({ error: 'missing-id', species: null });
    } else {
      const identity = this.accessIdentity;
      const scope = this.bs.accessSignal;
      const request = defer(() => scope.aborted || identity !== this.bs.cacheIdentity ? EMPTY : this.bs.getBooklet(bookletName)).pipe(
        map((response: string | BookletError) => (typeof response === 'string' ? this.parseXml(response) : response)),
        tap(booklet => {
          // Retry failures later; an old request must not evict a new access's cache.
          if (this.booklets[bookletName] === request) {
            if (isBooklet(booklet)) this.booklets[bookletName] = of(booklet);
            else delete this.booklets[bookletName];
          }
        }),
        // Snapshot replacement must not starve slow material. Explicit
        // connection/access cancellation still aborts the underlying read.
        takeUntil(merge(this.bs.connectionClosed$, fromEvent(scope, 'abort'))),
        finalize(() => {
          if (this.booklets[bookletName] === request) delete this.booklets[bookletName];
        }),
        shareReplay({ bufferSize: 1, refCount: false })
      );
      this.booklets[bookletName] = request;
    }
    return this.booklets[bookletName];
  }

  parseXml(xmlString: string): Booklet | BookletError {
    try {
      return this.parseBookletXml(xmlString);
    } catch (error) {
      return { error: 'xml', species: null };
    }
  }

  toBooklet(
    metadata: BookletMetadata,
    config: BookletConfig,
    customTexts: { [key: string]: string },
    states: { [key: string]: BookletState },
    units: Testlet
  ): Booklet {
    return {
      metadata,
      config,
      customTexts,
      states,
      units,
      species: this.getBookletSpecies(units)
    };
  }

  override toTestlet(testletDef: TestletDef<Testlet, Unit>, e: Element, context: ContextInBooklet<Testlet>): Testlet {
    return Object.assign(testletDef, {
      descendantCount: this.xmlCountChildrenOfTagNames(e, ['Unit']),
      blockId: `${context.localTestletIndex + 1}`,
      nextBlockId: `${context.localTestletIndex + 2}`
    });
  }

  // eslint-disable-next-line class-methods-use-this
  override toUnit(unitDef: UnitDef): Unit {
    return unitDef;
  }

  // eslint-disable-next-line class-methods-use-this
  override toBookletState(stateDef: BookletStateDef<BookletStateOption>): BookletState {
    const defaultOption = Object.values(stateDef.options).find(option => !option.conditions.length);
    return Object.assign(stateDef, {
      default: defaultOption?.id || Object.values(stateDef.options)[0].id
    });
  }

  // eslint-disable-next-line class-methods-use-this
  override toBookletStateOption(optionDef: BookletStateOptionDef): BookletStateOption {
    return optionDef;
  }

  // eslint-disable-next-line class-methods-use-this
  getBookletSpecies(units: Testlet): string {
    return `species: ${units.children.filter(testletOrUnit => !isUnit(testletOrUnit)).length}`;
  }
}

